private formatMatchInfo(match: MatchInfo, terms: string[]): FormattedMatch {
  return Object.entries(match).reduce((acc, [field, positions]) => {
    acc[field] = positions.map(pos => ({ position: pos, term: terms[0] }));
    return acc;
  }, {} as FormattedMatch);
}

